ield full"><label>Keperluan</label><textarea class="textarea" name="keperluan" required><?=e($item['keperluan']??'')?></textarea></div><div class="field full"><label>Catatan</label><textarea class="textarea" name="catatan"><?=e($item['catatan']??'')?></textarea></div></div><div class="form-actions"><a class="btn" href="<?=base_url('peminjaman')?>">Kembali</a><button class="btn btn-primary">Simpan</button></div></form></main><?php require __DIR__.'/../layouts/footer.php';?>
